import React, { useState, useEffect } from 'react';
import axios from 'axios';
import './index.css';

function App() {
  const [user, setUser] = useState(null);
  const [page, setPage] = useState('login');
  const [emailInput, setEmailInput] = useState('');
  const [data, setData] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [editingItem, setEditingItem] = useState(null);
  const [formData, setFormData] = useState({});

  const API = 'http://localhost:5000/api';

  // Debug log: Confirm App mounts
  useEffect(() => {
    console.log('App component mounted. Current page:', page);
  }, [page]);

  const login = async (e) => {
    e.preventDefault();
    if (!emailInput.trim()) return alert('Please enter your email');
    try {
      const res = await axios.post(`${API}/users/login`, { email: emailInput.trim() });
      setUser(res.data);
      setPage('dashboard');
    } catch (err) {
      alert('Login failed — user not found');
    }
  };

  const logout = () => {
    setUser(null);
    setPage('login');
    setEmailInput('');
    setShowForm(false);
    setEditingItem(null);
  };

  const load = async (endpoint) => {
    setLoading(true);
    try {
      const res = await axios.get(`${API}/${endpoint}`);
      setData(res.data);
    } catch (err) {
      console.error('Load error:', err);
      setData([]);
    }
    setLoading(false);
  };

  const goTo = (newPage) => {
    setPage(newPage);
    setShowForm(false);
    setEditingItem(null);
    const endpoint = getEndpoint(newPage);
    if (endpoint) load(endpoint);
  };

  // CRUD
  const startAdd = () => {
    setEditingItem(null);
    setFormData(getEmptyForm(page));
    setShowForm(true);
  };

  const startEdit = (item) => {
    setEditingItem(item);
    setFormData({ ...item });
    setShowForm(true);
  };

  const saveItem = async (e) => {
    e.preventDefault();
    const base = page === 'students' ? 'users' : page;
    let payload = { ...formData };
    if (page === 'courses') payload.instructorid = user.id;

    try {
      if (editingItem) {
        await axios.put(`${API}/${base}/${editingItem.id}`, payload);
        alert('Updated successfully!');
      } else {
        await axios.post(`${API}/${base}`, payload);
        alert('Created successfully!');
      }
      setShowForm(false);
      setEditingItem(null);
      load(getEndpoint(page));
    } catch (err) {
      console.error('Save error:', err);
      alert('Save failed: ' + (err.response?.data?.error || 'Check fields'));
    }
  };

  const deleteItem = async (id) => {
    if (!window.confirm('Delete this item permanently?')) return;
    const base = page === 'students' ? 'users' : page;
    try {
      await axios.delete(`${API}/${base}/${id}`);
      alert('Deleted');
      load(getEndpoint(page));
    } catch (err) {
      console.error('Delete error:', err);
      alert('Delete failed: ' + (err.response?.data?.error || 'Server error'));
    }
  };

  // Student actions
  const enroll = async (courseId) => {
    try {
      await axios.post(`${API}/courses/${courseId}/enroll`, { studentid: user.id });
      // Optimistic update: Add user.id to local course students
      setData(prevData => prevData.map(course => 
        course.id === courseId ? { ...course, students: [...(course.students || []), user.id] } : course
      ));
      alert('Enrolled successfully!');
      load('courses'); // Reload to confirm
    } catch (err) {
      console.error('Enroll error:', err);
      alert('Already enrolled or error');
    }
  };

  const drop = async (courseId) => {
    if (!window.confirm('Drop this course?')) return;
    try {
      await axios.post(`${API}/courses/${courseId}/drop`, { studentid: user.id });
      // Optimistic update: Remove user.id from local course students
      setData(prevData => prevData.map(course => 
        course.id === courseId ? { ...course, students: (course.students || []).filter(id => id !== user.id) } : course
      ));
      alert('Course dropped');
      load('courses'); // Reload to confirm
    } catch (err) {
      console.error('Drop error:', err);
      alert('Error dropping course');
    }
  };

  const submitAssignment = async (assignmentId) => {
    const url = prompt('Enter your submission link:');
    if (!url) return;
    try {
      await axios.post(`${API}/submissions`, {
        assignmentid: assignmentId,
        studentid: user.id,
        fileurl: url
      });
      alert('Submitted!');
      load(`submissions?studentid=${user.id}`);
    } catch (err) {
      console.error('Submit error:', err);
      alert('Submit failed');
    }
  };

  const gradeSubmission = async (submissionId) => {
    const grade = prompt('Enter grade (0-100):');
    if (grade === null) return;
    const feedback = prompt('Enter feedback:');
    try {
      await axios.put(`${API}/submissions/${submissionId}/grade`, { grade: parseInt(grade), feedback });
      alert('Graded!');
      load(getEndpoint(page));
    } catch (err) {
      console.error('Grade error:', err);
      alert('Grade failed');
    }
  };

  const isEnrolled = (course) => {
    console.log('Checking enrolled:', course.students, user.id); // Debug log
    return course.students && course.students.includes(user.id);
  };

  const getEndpoint = (p) => {
    switch (p) {
      case 'courses':
        return user.role === 'instructor' ? `courses?instructorid=${user.id}` : 'courses';
      case 'assignments':
        return user.role === 'instructor' ? 'assignments' : `assignments?courseid=${data.map(c => c.id).join(',') || ''}`; // Simplified
      case 'submissions':
        return `submissions?studentid=${user.id}`;
      case 'announcements':
        return 'announcements';
      case 'students':
        return 'users?role=student';
      default:
        return null;
    }
  };

  const getEmptyForm = (p) => {
    switch (p) {
      case 'courses':
        return { title: '', description: '' };
      case 'assignments':
        return { title: '', duedate: '', description: '', courseid: '' };
      case 'announcements':
        return { title: '', message: '', courseid: '' };
      case 'students':
        return { name: '', email: '', role: 'student' };
      default:
        return {};
    }
  };

  useEffect(() => {
    if (page === 'dashboard') goTo('courses');
  }, [page]);

  // Debug log: Before return
  console.log('Rendering App. User:', user, 'Page:', page);

  return (
    <div>
      {page === 'login' ? (
        <div className="container">
          <h1>Login</h1>
          <form onSubmit={login}>
            <input
              type="email"
              value={emailInput}
              onChange={(e) => setEmailInput(e.target.value)}
              placeholder="Enter email"
              required
            />
            <button type="submit" className="btn">Login</button>
          </form>
        </div>
      ) : (
        <>
          <nav>
            <a onClick={logout}>Logout</a>
            <a onClick={() => goTo('dashboard')}>Dashboard</a>
            {/* Add other nav links as in your original */}
          </nav>
          <div className="container">
            {/* ... (rest of the JSX as in your original, truncated in query but assume full) */}
          </div>
        </>
      )}
      <footer>{/* footer content */}</footer>
    </div>
  );
}

export default App;
